// Polyfills for Firebase Firestore WebChannel bug
if (typeof AbortController !== 'undefined') {
  AbortController.prototype.cancel = function() { this.abort(); };
}
if (typeof XMLHttpRequest !== 'undefined') {
  XMLHttpRequest.prototype.cancel = function() { this.abort(); };
}
if (typeof Promise !== 'undefined') {
  Promise.prototype.cancel = function() {};
}

