function togglePaymentDetails(val) {
  const bankDetails = document.getElementById('bank-details');
  if (val.includes('Bank Transfer') || val.includes('โอนเงินผ่านธนาคาร')) {
    bankDetails.style.display = 'block';
    // Not enforcing required on slip here to avoid strict blocking, just highly recommended.
  } else {
    bankDetails.style.display = 'none';
  }
}

// Global click listener to intercept "กดสั่งจองสินค้า" and "สั่งจองสินค้าเลยวันนี้" clicks
document.addEventListener('click', (e) => {
  const btn = e.target.closest('.btn-cta');
  if (btn) {
     const text = btn.textContent.trim().toUpperCase();
     if (text.includes('กดสั่งจองสินค้า') || text.includes('สั่งจองสินค้าเลยวันนี้') || text.includes('ADD TO CART')) {
       e.preventDefault();
       e.stopPropagation();
       // Inject Terms Modal if it doesn't exist
       if (!document.getElementById('terms-agreement-modal')) {
          document.body.insertAdjacentHTML('beforeend', `

    ×        
ข้อตกลงและเงื่อนไขการร่วมสนับสนุนโครงการ
(Terms & Conditions)        

ยินดีต้อนรับและขอขอบพระคุณทุกท่านที่ร่วมเป็นส่วนหนึ่งในการสนับสนุนโครงการพัฒนา Dent-Z Botanical Defense
      กรุณาอ่านและทำความเข้าใจเงื่อนไขด้านล่างนี้อย่างละเอียดก่อนทำการส่งเงินสนับสนุน (Donation):            
1. วัตถุประสงค์ของการรับเงินสนับสนุน      
เงินทุกบาททุกสตางค์ที่ท่านมอบให้ จะถูกนำไปใช้เป็นทุนในการวิจัย พัฒนา ทดสอบ และผลิตยาสีฟัน Dent-Z Botanical Defense เท่านั้น
      การส่งเงินนี้เป็น \"การสนับสนุนโครงการ (Donation/Contribution)\" เพื่อช่วยให้โครงการนี้เกิดขึ้นจริง ไม่ใช่การซื้อ-ขายสินค้าในระบบพาณิชย์ปกติ            
2. ความเสี่ยงและการยอมรับเงื่อนไข              
การพัฒนาผลิตภัณฑ์มีความเสี่ยง: เนื่องจากยาสีฟันเป็นผลิตภัณฑ์ที่ต้องผ่านการทดสอบมาตรฐาน ความปลอดภัย และขั้นตอนทางกฎหมาย ทางผู้พัฒนาอาจเผชิญกับอุปสรรคที่คาดไม่ถึง เช่น ผลลัพธ์ไม่เป็นไปตามเป้าหมาย ปัญหาด้านห่วงโซ่อุปทาน หรือการไม่ผ่านเกณฑ์มาตรฐานบางประการ        
กรณีที่โครงการไม่ประสบความสำเร็จ: หากเกิดเหตุสุดวิสัยที่ทำให้โครงการนี้ต้องยุติลง หรือไม่สามารถผลิตยาสีฟันสำเร็จรูปออกมาได้ ผู้พัฒนาจะแจ้งให้ผู้สนับสนุนทราบอย่างโปร่งใส และ ขอสงวนสิทธิ์ในการไม่คืนเงินสนับสนุนในทุกกรณี เนื่องจากเงินจำนวนดังกล่าวได้ถูกนำไปใช้จ่ายในกระบวนการวิจัยและพัฒนาไปแล้ว                  
3. ของตอบแทน      
เพื่อเป็นการขอบคุณ หากโครงการนี้สำเร็จลุล่วงด้วยดีและผลิตยาสีฟันได้ตามมาตรฐาน ผู้สนับสนุนจะได้รับยาสีฟันล็อตแรก และของที่ระลึกตามลำดับและเงื่อนไขที่กำหนดไว้

      กำหนดการส่งมอบของตอบแทนเป็นเพียง การคาดการณ์คร่าวๆ เท่านั้น อาจมีการเลื่อนออกไปตามความเหมาะสมของขั้นตอนการผลิต            
4. การยืนยันสิทธิ์      
เมื่อท่านกดปุ่ม \"ยอมรับเงื่อนไขและดำเนินการต่อ\" หรือทำการโอนเงินเรียบร้อยแล้ว จะถือว่าท่านได้อ่าน เข้าใจ และ ยอมรับความเสี่ยงและเงื่อนไขทั้งหมดที่ระบุไว้ข้างต้นนี้ด้วยความสมัครใจ    








สนใจสินค้า







รับโค้ดส่วนลดพิเศษ Early Bird 5-7% สำหรับการสั่งซื้อยาสีฟันล็อตแรก

