      behavior: "นอนดึกเกินที่ตั้งใจ พึ่งคาเฟอีน เลื่อนหรือข้ามกิจวัตรเมื่อเหนื่อย มีความสม่ำเสมอที่แกว่งไปมา",
      strength: "คุณเป็นคนที่ปรับตัวเก่งและมีความยืดหยุ่นสูง แม้จะเหนื่อยคุณก็ยังทำงานสร้างผลงานต่อได้",
      formula: ["สดชื่นแบบปลอบประโลม", "รีเซ็ตอย่างอ่อนโยน", "ไม่ทำให้แห้ง", "มิ้นต์สมดุล", "ฟื้นฟูมากกว่ากระตุ้นแรง"],
      ritual: "Restorative • Calm • Balanced • Resetting"
    },
    "The Quiet Type": {
      slogan: "“ความสงบคือความหรูหรา”",
      core: "คุณถูกดึงดูดโดยความเรียบง่าย ความสมดุล และความเสถียร คุณชอบประสบการณ์ที่รู้สึกสงบ คาดเดาได้ ไม่กระตุ้นมากเกินไป คุณไวต่อความซับซ้อนที่ไม่จำเป็น",
      behavior: "ชอบกิจวัตรที่มั่นคง หลีกเลี่ยงความรู้สึกที่แรงเกินไป ใช้สิ่งเดิมที่คุ้นเคยและรู้สึกปลอดภัย ให้ความสำคัญกับความสบาย",
      strength: "คุณมีความสม่ำเสมอในแบบเงียบ ๆ คุณไม่ทำให้กิจวัตรซับซ้อนเกินไป และนั่นช่วยรักษาความเสถียรของคุณไว้",
      formula: ["อ่อนโยน", "สมดุล", "ไม่ระคายเคือง", "ความเข้มต่ำ", "ใช้ง่ายทุกวัน"],
      ritual: "Simple • Calm • Stable • Effortless"
    }
  };

  const createDetailedCard = (matchedType) => {
    const info = data[matchedType];
    const container = document.createElement('div');
    container.className = 'personality-result-container';

    container.innerHTML = `

${info.slogan}



แก่นตัวตนของคุณ

${info.core}




พฤติกรรมและจุดแข็ง

${info.behavior}

จุดแข็ง: ${info.strength}




สูตรและ Ritual ที่เหมาะกับคุณ

          ${info.formula.map(f => `
${f}`).join('')}


${info.ritual}

    `;
    return container;
  };

  const showSuccessModal = () => {
    if (!document.getElementById('injected-success-modal')) {
      const modalHtml = `




            ×

✓

ส่งข้อความสำเร็จ!

เราได้รับข้อความของคุณเรียบร้อยแล้ว
ทีมงานจะรีบติดต่อกลับไปโดยเร็วที่สุด


ติดตามข่าวสารและสอบถามเพิ่มเติมผ่านช่องทาง:











      `;
      document.body.insertAdjacentHTML('beforeend', modalHtml);
    } else {
      document.getElementById('injected-success-modal').style.display = 'flex';
    }
  };

  // Pricing Logic
  const packagePrices = {
    "TESTER 7 g": 39,
    "REGULAR 30 g": 99,
    "BEST VALUE 100 g": 250
  };

  const calculateTotals = (form) => {
    const pkgSelect = form.querySelector('select[name="package"]');
    const qtyInput = form.querySelector('input[name="quantity"]');
    if (!pkgSelect || !qtyInput) return;

    let basePrice = 0;
    const val = pkgSelect.value;
    if (val.includes('TESTER')) basePrice = 39;
    else if (val.includes('REGULAR')) basePrice = 99;
    else if (val.includes('BEST VALUE')) basePrice = 250;
    const qty = parseInt(qtyInput.value) || 1;
    const subtotal = basePrice * qty;

    let donateAmt = 0;
    const activeRadio = form.querySelector('input[name="donate_preset"]:checked');
    const customInput = form.querySelector('input[placeholder*="Other amount"], input[placeholder*="ระบุจำนวนเงิน"]');

    // Read from radio by default
    if (activeRadio && activeRadio.value && activeRadio.value !== '0' && activeRadio.value !== 'other') {
      donateAmt = parseInt(activeRadio.value);
    }

    // Override if custom input has a valid number
    if (customInput && customInput.value && parseInt(customInput.value) >= 0) {
      donateAmt = parseInt(customInput.value) || 0;
      // Uncheck visually
      if (activeRadio && activeRadio.value !== 'other') {
        try { activeRadio.checked = false; } catch(e){}
        form.querySelectorAll('.donate-opt').forEach(lbl => lbl.classList.remove('active-donate'));
      }
    }

    const total = subtotal + donateAmt;
    const ht = form.querySelector('#hidden-net-total'); if(ht) { ht.value = '฿' + total; ht.classList.add('hidden-net-total-update'); }

    const subEl = form.querySelector('#display-subtotal');
    const donEl = form.querySelector('#display-donate');
    const totEl = form.querySelector('#display-total');

    if (subEl) subEl.innerText = '฿' + subtotal;
    if (donEl) donEl.innerText = '฿' + donateAmt;
    if (totEl) totEl.innerText = '฿' + total;
  };

  // Global Change/Input Listener for Checkout Calculator & Donate UI
  document.addEventListener('input', (e) => {
    // Intercept custom donate input to prevent React from clearing it
    const target = e.target;
    if (target.tagName === 'INPUT' && (target.placeholder.includes('Other amount') || target.placeholder.includes('ระบุจำนวนเงิน'))) {
      e.stopPropagation(); // Hide this input event from React
    }

    const form = target.closest && target.closest('.checkout-form');
    if (form) calculateTotals(form);
  }, true); // Use capture phase to intercept before React

  // Also stop keydown events for the custom input so React doesn't interfere
  document.addEventListener('keydown', (e) => {
    const target = e.target;
    if (target.tagName === 'INPUT' && (target.placeholder && (target.placeholder.includes('Other amount') || target.placeholder.includes('ระบุจำนวนเงิน')))) {
      e.stopPropagation();
    }
  }, true);

  ['change', 'input'].forEach(evt => document.addEventListener(evt, (e) => {
    const form = e.target.closest('.checkout-form');
    if (form && e.target.name === 'donate_preset') {
      // Clear custom input ONLY if a valid preset is clicked
      const customInput = form.querySelector('input[placeholder*="Other amount"], input[placeholder*="ระบุจำนวนเงิน"]');
      if (customInput && e.target.value !== 'other') {
        customInput.value = '';
      }

      // Update active styling
      form.querySelectorAll('.donate-opt').forEach(lbl => lbl.classList.remove('active-donate'));
      const lbl = e.target.closest('.donate-opt');
      if (lbl) lbl.classList.add('active-donate');

      calculateTotals(form);
    } else if (form) {
      calculateTotals(form);
    }
  }));

  // Intercept the checkout & consult forms in CAPTURE phase to beat React 17
  document.addEventListener('submit', async (e) => {
    const form = e.target;
    if ((form.classList && form.classList.contains('checkout-form')) || (form.action && form.action.includes('formsubmit.co'))) {
      e.preventDefault(); 
      e.stopPropagation(); // Stop React from interfering

      const isCheckout = form.classList && form.classList.contains('checkout-form');
      const submitBtn = form.querySelector('button[type="submit"]') || form.querySelector('input[type="submit"]');
      const originalText = submitBtn ? (submitBtn.innerText || submitBtn.value) : '';
      if (submitBtn) {
        if (submitBtn.innerText) submitBtn.innerText = 'กำลังดำเนินการ...';
        else if (submitBtn.value) submitBtn.value = 'กำลังดำเนินการ...';
        submitBtn.disabled = true;
      }

      const rawFormData = new FormData(form);
      const translatedKeys = {
        'Net_Total': 'Net_Total (ยอดรวมสุทธิ)',
        'name': 'name (ชื่อ-นามสกุล)',
        'phone': 'phone (เบอร์โทรศัพท์)',
        'email': 'email (อีเมล)',
        'address': 'address (ที่อยู่จัดส่ง)',
        'package': 'package (แพ็กเกจที่ต้องการ)',
        'quantity': 'quantity (จำนวนสินค้า)',
        'donate_preset': 'donate_preset (เงินสมทบทุน)',
        'donate_custom': 'donate_custom (จำนวนเงินที่ระบุเอง)',
        'message': 'message (ข้อความ)'
      };

      const formData = new FormData();
      for (let [key, value] of rawFormData.entries()) {
        const newKey = translatedKeys[key] || key;
        formData.append(newKey, value);
        // Keep original email field to ensure FormSubmit's Autoresponse and Reply-To features still work
        if (key === 'email') {
          formData.append('email', value);
        }
      }

      // ===== DENT-Z ANALYTICS: Fire-and-forget order save =====
      if (isCheckout) {
        try {
          const orderPayload = {
            name: rawFormData.get('name') || rawFormData.get('name (ชื่อ-นามสกุล)') || '',
            phone: rawFormData.get('phone') || rawFormData.get('phone (เบอร์โทรศัพท์)') || '',
            email: rawFormData.get('email') || rawFormData.get('email (อีเมล)') || '',
            address: rawFormData.get('address') || rawFormData.get('address (ที่อยู่จัดส่ง)') || '',
            package: rawFormData.get('package') || rawFormData.get('package (แพ็กเกจที่ต้องการ)') || '',
            quantity: parseFloat(rawFormData.get('quantity') || rawFormData.get('quantity (จำนวนสินค้า)') || '1'),
            net_total: parseFloat((rawFormData.get('Net_Total') || rawFormData.get('Net_Total (ยอดรวมสุทธิ)') || '0').replace('฿','').replace(/,/g,'').trim()),
            donate_preset: parseFloat(rawFormData.get('donate_preset') || rawFormData.get('donate_preset (เงินสมทบทุน)') || '0'),
            donate_custom: parseFloat(rawFormData.get('donate_custom') || rawFormData.get('donate_custom (จำนวนเงินที่ระบุเอง)') || '0'),
            userId: window.globalAuth && window.globalAuth.currentUser ? window.globalAuth.currentUser.uid : 'anonymous'
          };
          if (window.saveOrderToFirestore) {
            window.saveOrderToFirestore(orderPayload); // fire-and-forget
          }
        } catch(analyticsErr) {
          console.warn('[Analytics] Could not capture order data:', analyticsErr);
        }
      }
      // ===== END DENT-Z ANALYTICS =====

      // Safety Append: Make sure _autoresponse goes through in the AJAX body
      if (rawFormData.get('email')) {
        const msg = isCheckout ? 
          'ขอบคุณสำหรับการสั่งจองสินค้า Dent-Z! เราได้รับคำสั่งจองสินค้าของคุณแล้ว และจะดำเนินการจัดส่งให้เร็วที่สุด' : 
          'ได้รับข้อความปรึกษาปัญหาผิวของคุณแล้ว! ทีมงานจะรีบตอบกลับโดยเร็วที่สุดครับ';

        if (!formData.has('_autoresponse')) {
          formData.append('_autoresponse', msg);
        } else {
          formData.set('_autoresponse', msg);
        }
      }

      let actionUrl = form.action;
      if (!actionUrl.includes('/ajax/')) {
        actionUrl = actionUrl.replace('formsubmit.co/', 'formsubmit.co/ajax/');
      }

      try {
        await fetch(actionUrl, {
          method: "POST",
          headers: {
              'Accept': 'application/json'
          },
          body: formData // Use FormData natively to support File Uploads (Slip)
        });

        // Hide modal if exists
        let curr = form;
        while(curr && curr.tagName !== 'BODY') {
          if(curr.getAttribute('role') === 'dialog' || curr.id === 'checkout-modal') {
            curr.style.display = 'none'; 
            break;
          }
          curr = curr.parentElement;
        }

        // Show Success modal
        showSuccessModal();
        form.reset();
        if(typeof calculateTotals === 'function') calculateTotals(form);
      } catch (err) {
        console.error("AJAX submit failed:", err);
        alert("เกิดข้อผิดพลาดในการส่งข้อมูล กรุณาลองใหม่อีกครั้ง");
      } finally {
        if (submitBtn) {
          if (submitBtn.innerText) submitBtn.innerText = originalText;
          else if (submitBtn.value) submitBtn.value = originalText;
          submitBtn.disabled = false;
        }
      }
    }
  }, true);

  const observer = new MutationObserver(() => {

  const styleId = 'dentz-modal-widen-style';
  if (!document.getElementById(styleId)) {
    const style = document.createElement('style');
    style.id = styleId;
    style.innerHTML = `
      div[role="dialog"] .bg-white { 
         width: 95vw !important; 
         max-width: 800px !important; 
      }
      div[role="dialog"] .sm\\:max-w-lg, div[role="dialog"] .sm\\:w-full {
         max-width: 800px !important;
         width: 95vw !important;
      }
      /* specifically target profile */
      div[role="dialog"] > div > div > div {
         max-width: 800px !important;
      }
      #root { display: flex !important; flex-direction: column !important; min-height: 100vh !important; }
      #root > footer { margin-top: auto !important; }

      .article-modal-content { box-sizing: border-box !important; max-height: 85vh !important; margin: auto !important; }
      .article-modal-overlay { align-items: flex-start !important; padding-top: 5vh !important; padding-bottom: 5vh !important; overflow-y: auto !important; }
    `;
    document.head.appendChild(style);
  }

  const elements = document.querySelectorAll('p, span, div, h1, h2, h3, h4, h5, h6');

  // Autoresponder
  document.querySelectorAll('form').forEach(form => {
    if (form.action && form.action.includes('formsubmit.co')) {
      if (!form.querySelector('input[name="_autoresponse"]')) {
        const autoResp = document.createElement('input');
        autoResp.type = 'hidden';
        autoResp.name = '_autoresponse';
        if (form.classList && form.classList.contains('checkout-form')) {
          autoResp.value = 'ขอบคุณสำหรับการสั่งจองสินค้า Dent-Z! เราได้รับคำสั่งจองสินค้าของคุณแล้ว และจะดำเนินการจัดส่งให้เร็วที่สุด';
        } else {
          autoResp.value = 'ได้รับข้อความปรึกษาปัญหาผิวของคุณแล้ว! ทีมงานจะรีบตอบกลับโดยเร็วที่สุดครับ';
        }
        form.appendChild(autoResp);
      }
    }
  });

  // Calculate totals
  document.querySelectorAll('.checkout-form').forEach(form => {
    if (!form.dataset.initializedCalc && typeof calculateTotals === 'function') {
      calculateTotals(form);
      form.dataset.initializedCalc = 'true';
    }
  });

  // Widen modal
  for (let el of elements) {
    if (el.textContent.includes('โปรไฟล์ของฉัน') || el.textContent.includes('รายละเอียดการสั่งจองสินค้า')) {
      let curr = el;
      while(curr && curr.tagName !== 'BODY') {
        if (curr.getAttribute('role') === 'dialog' || (curr.classList && curr.classList.contains('article-modal-content'))) {
           if (curr.classList.contains('article-modal-content')) {
               curr.style.setProperty('width', '95vw', 'important');
               curr.style.setProperty('max-width', '800px', 'important');
           } else {
               curr.style.setProperty('width', '100%', 'important');
               if (curr.firstElementChild) {
                 curr.firstElementChild.style.setProperty('width', '95vw', 'important');
                 curr.firstElementChild.style.setProperty('max-width', '800px', 'important');
                 if (curr.firstElementChild.firstElementChild) {
                   curr.firstElementChild.firstElementChild.style.setProperty('width', '100%', 'important');
                   curr.firstElementChild.firstElementChild.style.setProperty('max-width', '800px', 'important');
                 }
               }
           }
           break;
        }
        curr = curr.parentElement;
      }
    }
  }

  // 1. Quiz Result Modal
  let quizParent = null;
  let placeholderNode = null;
  let foundType = null;

  for (let el of elements) {
    if ((el.textContent.includes('ขอบคุณที่ร่วมประเมิน') || el.textContent.includes('เราจะแนะนำผลิตภัณฑ์')) && el.children.length === 0) {
      placeholderNode = el;
      quizParent = el.parentElement;
      break;
    }
  }

  if (quizParent) {
    for (const type in data) {
      if (quizParent.textContent.includes(type)) {
        foundType = type;
        break;
      }
    }

    if (foundType) {
      if (!quizParent.querySelector('.personality-result-container')) {
        if (placeholderNode) placeholderNode.style.display = 'none';

        // Hide native title
        for (let child of quizParent.children) {
           if (child.textContent.includes(foundType) && child.tagName !== 'DIV') {
              child.style.display = 'none';
           }
        }

        quizParent.appendChild(createDetailedCard(foundType));

        if (cachedLatestResult !== foundType) {
          cachedLatestResult = foundType;
          localStorage.setItem('dentz_result_guest', foundType);
        }
      }
    }
  }

  // 2. Profile Display
  let profileNoResultNode = null;
  let profileResultHeaderNode = null;

  for (let el of elements) {
    const text = el.textContent.trim();
    if (text.includes('ยังไม่มีประวัติการทำแบบทดสอบ')) profileNoResultNode = el;
    if (text.includes('ผลการประเมินล่าสุด:') && el.children.length <= 1) profileResultHeaderNode = el;

    if (text === 'ยังไม่มีประวัติการสั่งจองสินค้า') el.style.display = 'none';
    if (el.tagName === 'H3' && text.includes('ประวัติการสั่งจองสินค้า')) {
      if (el.parentElement) el.parentElement.style.display = 'none';
    }
  }

  // To make it real-time, read the type directly from the profile modal if it's open
  let profileTextType = null;
  if (profileResultHeaderNode && profileResultHeaderNode.parentElement) {
     const text = profileResultHeaderNode.parentElement.textContent;
     for (const type in data) {
        if (text.includes(type)) { profileTextType = type; break; }
     }
  }

  let typeToShow = profileTextType || cachedLatestResult;

  if (typeToShow) {
    let targetContainer = null;
    if (profileNoResultNode) {
      profileNoResultNode.style.display = 'none';
      targetContainer = profileNoResultNode.parentElement;
    } else if (profileResultHeaderNode) {
      targetContainer = profileResultHeaderNode.parentElement;
      if (targetContainer && targetContainer.parentElement) {
          targetContainer = targetContainer.parentElement;
      }
    }

    if (targetContainer) {
      let existingCard = targetContainer.querySelector('.personality-result-container');
      let existingTitle = targetContainer.querySelector('.injected-type-title');

      // If the card exists but the type has changed, remove it
      if (existingTitle && existingTitle.textContent !== typeToShow) {
         if (existingCard) existingCard.remove();
         existingTitle.remove();
         existingCard = null;
      }

      if (!existingCard) {
        const typeTitle = document.createElement('h3');
        typeTitle.style.color = '#195c2c';
        typeTitle.style.marginTop = '0.5rem';
        typeTitle.style.marginBottom = '0';
        typeTitle.textContent = typeToShow;
        typeTitle.className = 'injected-type-title';

        const charDesc = targetContainer.querySelector('p');
        if (charDesc && charDesc.textContent.includes('คาแรคเตอร์ของคุณคือ')) {
            charDesc.style.display = 'none';
        }

        targetContainer.appendChild(typeTitle);
        targetContainer.appendChild(createDetailedCard(typeToShow));
      }
    }
  }

});

observer.observe(document.body, { childList: true, subtree: true });



  // Foolproof way to remove any rogue text nodes at the bottom of the body
  document.addEventListener("DOMContentLoaded", function() {
      const cleanUp = () => {
          Array.from(document.body.childNodes).forEach(node => {
              if (node.nodeType === Node.TEXT_NODE) {
                  node.remove();
              }
          });
      };
      cleanUp();
      setTimeout(cleanUp, 500);
      setTimeout(cleanUp, 1500);
  });




  (function initCarousel() {
    const checkExist = setInterval(function() {
       const carousel = document.querySelector('.articles-carousel');
       if (carousel && carousel.children.length > 2) {
          clearInterval(checkExist);

          let isHovered = false;
          carousel.addEventListener('mouseenter', () => isHovered = true);
          carousel.addEventListener('mouseleave', () => isHovered = false);
          carousel.addEventListener('touchstart', () => isHovered = true);
          carousel.addEventListener('touchend', () => { setTimeout(() => isHovered = false, 1000); });

          let currentScroll = 0;
          function autoScroll() {
             if (!isHovered) {
                currentScroll += 0.8;
                carousel.scrollLeft = currentScroll;

                if (Math.abs(currentScroll - carousel.scrollLeft) > 2) {
                    currentScroll = carousel.scrollLeft;
                }

                const halfCount = Math.floor(carousel.children.length / 2);
                const loopPoint = carousel.children[halfCount].offsetLeft - carousel.children[0].offsetLeft;
                if (carousel.scrollLeft >= loopPoint) {
                   currentScroll -= loopPoint;
                   carousel.scrollLeft = currentScroll;
                }
             } else {
                 currentScroll = carousel.scrollLeft;
             }
             requestAnimationFrame(autoScroll);
          }
          requestAnimationFrame(autoScroll);
       }
    }, 500);
  })();



  // Robust Background Sync for Cross-Device Quiz Results (V3)
  setInterval(async () => {
    if (window.globalAuth && window.globalAuth.currentUser && window.saveQuizToFirestore) {
      const localQuiz = localStorage.getItem('dentz_result_guest');
      if (localQuiz) {
        try {
          const success = await window.saveQuizToFirestore(window.globalAuth.currentUser.uid, {type: localQuiz, date: new Date().toISOString()});
          if (success !== false) {
             localStorage.removeItem('dentz_result_guest');
             console.log('Cross-device sync: Saved local quiz result to Firestore and cleared local cache.');
          } else {
             console.warn('Cross-device sync: Firestore save failed, keeping local cache.');
          }
        } catch (error) {
          console.error('Cross-device sync failed:', error);
        }
      }
    }
  }, 2000);


